SELECT p.gender
FROM patient p
WHERE p.uniquepid = '017-41154';

SELECT MAX(treatmenttime) as most_recent_stay_time
FROM treatment
WHERE patientunitstayid = '002-75209';

SELECT DISTINCT (
    MIN(vitalperiodic.respiration) AS first_respiration,
    MAX(vitalperiodic.respiration) AS last_respiration
) FROM vitalperiodic
WHERE patientunitstayid = '027-82318'
GROUP BY vitalperiodic.respiration;

SELECT CASE
    WHEN (
        (SELECT AVG(labresult) FROM lab WHERE patientunitstayid = 013-23115 AND labresulttime < (SELECT MAX(labresulttime) FROM lab WHERE patientunitstayid = 013-23115))
        > (
            (SELECT AVG(labresult) FROM lab WHERE patientunitstayid = 013-23115 AND labresulttime > (SELECT MIN(labresulttime) FROM lab WHERE patientunitstayid = 013-23115))
        )
    ) THEN 1 ELSE 0 END
FROM patient
WHERE uniquepid = '013-23115';

SELECT percentile(
    (SELECT AVG(microlab.cellvaluenumeric) FROM microlab WHERE patientunitstayid = 006-254232 AND age = (SELECT age FROM patient WHERE uniquepid = 006-254232)),
    100
) AS percentile;

SELECT COUNT(DISTINCT CASE WHEN admissiontime IS NOT NULL THEN admissiontime END) as days_since_admission
FROM patient
WHERE uniquepid = '015-59552';

SELECT COUNT(DISTINCT CASE WHEN admissiontime IS NOT NULL THEN admissiontime END) as days_since_admission
FROM patient
WHERE uniquepid = '022-78423';

SELECT CAST(SUM(CASE WHEN admissiontime < CURRENT_DATE() THEN 1 ELSE 0 END) AS INTEGER) * 24 AS hours_since_admission
FROM patient
WHERE uniquepid = '021-80293';

SELECT COUNT(DISTINCT CASE WHEN (
    (SELECT COUNT(*) FROM intakeoutput WHERE patientunitstayid = '004-79017' AND cellpath = 'venous catheter' AND celllabel = 'hemodialysis' AND intakeoutputtime < CURRENT_TIMESTAMP())
)
) AS days_since_last_insertion;

SELECT DISTINCT p.uniquepid
FROM patient p
WHERE p.patienthealthsystemstayid = 030-47098;

SELECT DISTINCT d.diagnosisid, d.diagnosisname
FROM diagnosis d
WHERE d.patientunitstayid = 030-31704;

SELECT COUNT(*) AS patient_count
FROM patient
WHERE admissionheight > 0 AND admissionweight > 0 AND admissiontime IS NOT NULL;

SELECT COUNT(*) as current_patients_30s
FROM patient
WHERE age >= 30 AND age <= 39;

SELECT AVG(c.cost)
FROM cost c
WHERE c.uniquepid = (SELECT uniquepid FROM patient WHERE patienthealthsystemstayid = (SELECT patienthealthsystemstayid FROM patient WHERE patientunitstayid = (SELECT patientunitstayid FROM patient WHERE diagnosisname LIKE '%ceftriaxone%' OR diagnosisname LIKE '%ceftriaxone%')));

SELECT COUNT(DISTINCT patientunitstayid)
FROM patient
WHERE patientunitstayid <= (
    SELECT MIN(patientunitstayid)
    FROM patient
    WHERE patientadmittime <= (
        CURRENT_DATE - INTERVAL '6 years'
    )
)
AND patientunitstayid != 0;

SELECT CASE
    WHEN (
        (SELECT MAX(vitalperiodic.temperature) FROM vitalperiodic WHERE patientunitstayid = 006-146580)
        < (
            SELECT MAX(vitalperiodic.temperature) FROM vitalperiodic WHERE patientunitstayid = 006-146580
        )
    ) THEN 1 ELSE 0 END
FROM patient
WHERE uniquepid = '006-146580';

SELECT CAST(SUBSTR(SUBSTRING(patienthealthsystemstayid, 1, 10), 1) AS INTEGER) AS age
FROM patient
WHERE patienthealthsystemstayid = '003-39001';

SELECT COUNT(DISTINCT CASE WHEN admissiontime IS NOT NULL THEN admissiontime END) as days_since_admission
FROM patient
WHERE uniquepid = '012-31752';

SELECT COUNT(DISTINCT CASE WHEN admissiontime IS NOT NULL THEN admissiontime END) as days_since_admission
FROM patient
WHERE uniquepid = '021-111547';

SELECT CAST(SUM(CASE WHEN admissiontime < CURRENT_DATE() THEN 1 ELSE 0 END) AS INTEGER) * 24 AS hours_since_admission
FROM patient
WHERE uniquepid = '010-21105';

SELECT COUNT(DISTINCT CASE WHEN admissiontime < '2005-12-31 23:59:00' THEN admissiontime ELSE NULL END) AS days_since_admission
FROM patient
WHERE uniquepid = '022-187132';

SELECT COUNT(DISTINCT CASE WHEN (
    (SELECT COUNT(*) FROM treatment WHERE treatmentid = patientunitstayid AND treatmentname = '0.9% 1,000 ml' AND treatmenttime >= '2025-12-31 23:59:00'
)
)
)
FROM patient;

SELECT CASE
    WHEN (
        (SELECT COUNT(*) FROM patient WHERE patienthealthsystemstayid = 0166009 AND patientunitstayid = 0166009) > 0
    ) THEN 'Yes'
    ELSE 'No'
END AS has_ivf;

SELECT MAX(CAST(COUNT(DISTINCT CASE WHEN (YEAR(CURRENT_DATE) = YEAR(2103) AND MONTH(CURRENT_DATE) = MONTH(2103)) AS INTEGER)) AS INTEGER) - 1
FROM patient
WHERE uniquepid = '016-26907';

SELECT MAX(admissionweight)
FROM patient
WHERE uniquepid = '005-88011';

SELECT MIN(vitalperiodic.temperature)
FROM vitalperiodic
WHERE patientunitstayid = '022-84707';

SELECT COUNT(DISTINCT CASE WHEN (SELECT COUNT(*) FROM lab WHERE labid = 1 AND patientunitstayid = 035-24054) THEN 1 ELSE 0 END) as platelets_count
FROM patient
WHERE patientunitstayid = 035-24054;

SELECT COUNT(DISTINCT patient.uniquepid)
FROM patient
WHERE age >= 30 AND age < 40;

SELECT COUNT(DISTINCT p.uniquepid)
FROM patient p
WHERE p.patienthealthsystemstayid >= (
    (2105-12-31 23:59:00 - 2105-12-31 23:59:00)
)
AND p.patienthealthsystemstayid <= (
    (2105-12-31 23:59:00 + 5 years)
)
AND p.patienthealthsystemstayid != 0;

